from scipy import ndimage
import numpy as np, json

def transform(grid):
    g=[row[:] for row in grid]; a=np.array(g)
    boxes=[]
    for color in set(a.flat)-{0}:
        ys,xs=np.where(a==color)
        y0,y1,x0,x1=ys.min(),ys.max(),xs.min(),xs.max()
        boxes.append((color,y0,y1,x0,x1))
    # source: box with non-empty interior
    src=None
    for b in boxes:
        c,y0,y1,x0,x1=b
        inter=a[y0+1:y1,x0+1:x1]
        if (inter==c).any():
            src=b; pat=inter.copy(); break
    c,sy0,sy1,sx0,sx1=src
    for b in boxes:
        c2,y0,y1,x0,x1=b
        if b==src: continue
        inter=a[y0+1:y1,x0+1:x1]
        if inter.shape==pat.shape:
            for i in range(pat.shape[0]):
                for j in range(pat.shape[1]):
                    if pat[i,j]: a[y0+1+i,x0+1+j]=c2
        elif not (inter==c2).any():
            # empty mismatched box: erase
            a[y0:y1+1,x0:x1+1]=0
    return a.tolist()

